<script setup lang="ts">
import {pmsFetch,withoutPmsLoader} from './loading';
import PmsProjectGrid from './PmsProjectGrid.vue';
import PmsSprintBoard from './PmsSprintBoard.vue';
import PmsMultiSelect from './PmsMultiSelect.vue';
import PmsFormDialog from './PmsFormDialog.vue';
import PmsTableControls from './PmsTableControls.vue';
import PmsDescriptionEditor from './PmsDescriptionEditor.vue';
import PmsProjectChat from './PmsProjectChat.vue';
import PmsSubmissions from './PmsSubmissions.vue';
import PmsTaskDetail from './PmsTaskDetail.vue';
import PmsMyWorkAssignees from './PmsMyWorkAssignees.vue';
import {ref,computed,onMounted,onUnmounted,nextTick,watch} from 'vue';
const clientId=ref(Number(new URLSearchParams(location.search).get('client'))||null);const departmentId=ref(Number(new URLSearchParams(location.search).get('department'))||null);const departmentOverview=ref(new URLSearchParams(location.search).get('section')==='project-departments');
const quickAssignment=ref<any>(null);const taskList=ref<any>(null),statusMenu=ref<number|null>(null),approvalMenu=ref<number|null>(null);const taskSearch=ref(''),taskListPage=ref(1),taskListSize=ref(10);const filteredTaskList=computed(()=>taskList.value?.tasks.filter((t:any)=>t.title.toLowerCase().includes(taskSearch.value.toLowerCase()))||[]);const taskListRows=computed(()=>taskListSize.value<0?filteredTaskList.value:filteredTaskList.value.slice((taskListPage.value-1)*taskListSize.value,taskListPage.value*taskListSize.value));const restoring=ref(true);const issueAction=ref('');const submissionsOpen=ref(false),workloadOpen=ref(false),discussionOpen=ref(false);const dragged=ref<number|null>(null);const assignment=ref<any>(null),assignmentIds=ref<number[]>([]);const props=defineProps<{csrf?:string;permissions:string[];initialProject?:number|null;createDepartment?:number|null}>();const approvalFilter=ref(''),sortKey=ref('id'),sortAscending=ref(false),preview=ref<any>(null),listDiscussion=ref<any>(null),listSubmission=ref<any>(null);const statusFilter=ref(''),search=ref(''),tablePage=ref(1),tableSize=ref(10);const paged=computed(()=>tableSize.value<0?shown.value:shown.value.slice((tablePage.value-1)*tableSize.value,tablePage.value*tableSize.value));const shown=computed(()=>page.value?.projects?.filter((p:any)=>p.name.toLowerCase().includes(search.value.toLowerCase())&&(!statusFilter.value||p.status===statusFilter.value)&&(!approvalFilter.value||p.approval===approvalFilter.value)).sort((a:any,b:any)=>{const av=a[sortKey.value],bv=b[sortKey.value];return (typeof av==='number'?av-bv:String(av||'').localeCompare(String(bv||'')))*(sortAscending.value?1:-1);})||[]);const issue=ref<number|null>(null);const page=ref<any>(null),board=ref<any>(null),workflowFilter=ref(''),sprintFilter=ref(new URLSearchParams(location.search).get('sprint')||''),sprintEditor=ref<any>(null),editor=ref<any>(null),task=ref<any>(null),busy=ref(false),error=ref('');const can=(k:string)=>props.permissions.includes('*')||props.permissions.includes(k);const columns=computed(()=>board.value?.selectedWorkflow?.columns||[]);
async function api(path:string,method='GET',body?:any){const form=body instanceof FormData;const r=await pmsFetch('/pms/api/'+path,{method,headers:{Accept:'application/json','X-CSRF-TOKEN':props.csrf||'',...(form?{}:{'Content-Type':'application/json'})},body:body?(form?body:JSON.stringify(body)):undefined});const d=await r.json();if(!r.ok)throw Error(Object.values(d.errors||{}).flat().join(' ')||d.message||'Unable to complete this action.');return d;}
async function perform(fn:()=>Promise<void>){busy.value=true;error.value='';try{await fn();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function openWorkload(){workloadOpen.value=true;await nextTick();document.querySelector<HTMLElement>('.pms-workload-sidebar [role=dialog]')?.focus();}
async function viewTasks(p:any){await perform(async()=>{taskList.value=(await api('projects/'+p.id+'/task-list')).data;taskSearch.value='';taskListPage.value=1;});}
async function load(){await perform(async()=>{page.value=(await api('projects'+(clientId.value?'?client='+clientId.value:''))).data;});}
function boardPath(id:number){if(departmentOverview.value)return 'projects/'+id+'/departments';const q=new URLSearchParams();if(departmentId.value)q.set('department',String(departmentId.value));if(sprintFilter.value)q.set('sprint',sprintFilter.value);return 'projects/'+id+'?'+q;}
async function open(id:number,scroll=false){
 const overview=departmentOverview.value,version=++overviewVersion;
 const url=new URL(location.href);url.searchParams.set('section',overview?'project-departments':'project-board');url.searchParams.set('project',String(id));
 if(clientId.value)url.searchParams.set('client',String(clientId.value));
 if(overview)url.searchParams.delete('department');else if(departmentId.value)url.searchParams.set('department',String(departmentId.value));
 if(workflowFilter.value)url.searchParams.set('workflow',workflowFilter.value);else url.searchParams.delete('workflow');
 if(sprintFilter.value)url.searchParams.set('sprint',sprintFilter.value);else url.searchParams.delete('sprint');
 history.replaceState(null,'',url);window.dispatchEvent(new Event('pms:navigation'));
 if(overview){
  overviewProjectId.value=id;overviewLoading.value=true;error.value='';
  if(board.value?.project?.id!==id)board.value=null;
  try{
   const response=await withoutPmsLoader(()=>api('projects/'+id+'/departments'));
   if(version!==overviewVersion||!departmentOverview.value)return;
   board.value=response.data;rememberClient(board.value.project);
   if(!page.value)await load();
   if(version===overviewVersion&&scroll){await nextTick();departmentPanel.value?.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});}
  }catch(e){if(version===overviewVersion)error.value=(e as Error).message;}
  finally{if(version===overviewVersion)overviewLoading.value=false;}
 }else{
  overviewLoading.value=false;
  await perform(async()=>{try{const response=await api(boardPath(id));if(version!==overviewVersion)return;board.value=response.data;rememberClient(board.value.project);}catch(e){if(version!==overviewVersion)return;if(board.value&&overviewProjectId.value===id){departmentOverview.value=true;departmentId.value=null;const fallback=new URL(location.href);fallback.searchParams.set('section','project-departments');fallback.searchParams.delete('department');fallback.searchParams.delete('sprint');history.replaceState(null,'',fallback);window.dispatchEvent(new Event('pms:navigation'));}throw e;}});
 }
}
async function assignProject(){await perform(async()=>{await api('project-assignments','POST',{projectId:assignment.value.id,userId:assignmentIds.value.join(',')});assignment.value=null;assignmentIds.value=[];page.value=(await api('projects'+(clientId.value?'?client='+clientId.value:''))).data;});}
async function removeProjectUser(p:any,u:any){if(confirm('Remove '+u.name+' from this project?'))await perform(async()=>{await api('project-assignments','DELETE',{project_id:p.id,user_id:u.id});page.value=(await api('projects'+(clientId.value?'?client='+clientId.value:''))).data;assignment.value=null;});}
function newProject(){editor.value={client_id:clientId.value||'',name:'',company_name:'',description:'',url:'',start_date:'',end_date:'',workflow_ids:[],department_ids:props.createDepartment?[props.createDepartment]:[],image:null,attachment:null};}
async function editProject(p:any){await perform(async()=>{const d=await api('projects/'+p.id+'/edit');editor.value={...d.data,start_date:d.data.start_date?.slice(0,10)||'',end_date:d.data.end_date?.slice(0,10)||'',company_name:d.data.company?.name||'',workflow_ids:d.workflow_ids,department_ids:d.department_ids,sync_departments:1,image:null,attachment:null};});}
async function deleteProject(p:any){if(!confirm('Delete project '+p.name+'?'))return;await perform(async()=>{await api('projects/'+p.id,'DELETE');page.value=(await api('projects'+(clientId.value?'?client='+clientId.value:''))).data;if(overviewProjectId.value===p.id)clearProjectSelection();window.dispatchEvent(new Event('pms:hierarchy-changed'));});}
async function projectStatus(p:any,status:string){await perform(async()=>{await api('project-status','POST',{id:p.id,status});statusMenu.value=null;page.value=(await api('projects'+(clientId.value?'?client='+clientId.value:''))).data;});}
function form(value:any){const f=new FormData();for(const [key,v] of Object.entries(value)){if(Array.isArray(v))v.forEach(x=>f.append(key+'[]',x instanceof File?x:String(x)));else if(v instanceof File)f.append(key,v);else if(v!==''&&v!=null)f.append(key,String(v));}return f;}
async function saveProject(){await perform(async()=>{const editing=editor.value.id;const r=await api('projects'+(editing?'/'+editing:''),'POST',form(editor.value));editor.value=null;page.value=(await api('projects'+(clientId.value?'?client='+clientId.value:''))).data;if(board.value)await open(board.value.project.id);window.dispatchEvent(new Event('pms:hierarchy-changed'));});}
function newTask(){task.value={title:'',description:'',due_date:'',priority:1,status:'pending',department_id:departmentId.value,project_id:board.value.project.id,workflow_id:board.value.selectedWorkflow?.id,workflow_column_id:columns.value[0]?.id,assignee_ids:[],sprint_id:board.value.selectedSprint?.id||'',attachments:[]};}
async function saveTask(){await perform(async()=>{await api('tasks','POST',form(task.value));task.value=null;board.value=(await api(boardPath(board.value.project.id))).data;});}
async function drop(column:any,position?:number){if(!dragged.value||busy.value||!can('task-status'))return;const id=dragged.value;dragged.value=null;await perform(async()=>{const result=await api('tasks/'+id+'/board','PATCH',{workflow_column_id:column.id,workflow_id:board.value.selectedWorkflow.id,position:position??board.value.boardTasks.filter((t:any)=>t.workflow_column_id===column.id).length});const card=board.value.boardTasks.find((t:any)=>t.id===id);if(card&&result.task)Object.assign(card,result.task);});}
async function move(t:any,event:Event){if(busy.value)return;await perform(async()=>{const result=await api('tasks/'+t.id+'/board','PATCH',{workflow_column_id:Number((event.target as HTMLSelectElement).value),workflow_id:board.value.selectedWorkflow.id});const card=board.value.boardTasks.find((card:any)=>card.id===t.id);if(card&&result.task)Object.assign(card,result.task);});}
async function approval(p:any,status:string){await perform(async()=>{await api('projects/'+p.id+'/approval','POST',{status});approvalMenu.value=null;page.value=(await api('projects'+(clientId.value?'?client='+clientId.value:''))).data;});}
async function saveSprint(){await perform(async()=>{const result=await api(sprintEditor.value.id?'sprints/'+sprintEditor.value.id:'projects/'+board.value.project.id+'/sprints',sprintEditor.value.id?'PUT':'POST',{...sprintEditor.value,department_id:departmentId.value,start_date:sprintEditor.value.start_date||null,end_date:sprintEditor.value.end_date||null});if(!sprintEditor.value.id)sprintFilter.value=String(result.sprint.id);sprintEditor.value=null;await open(board.value.project.id);});}
async function deleteSprint(){if(!board.value.selectedSprint||!confirm('Delete this sprint and move its tasks to the backlog?'))return;await perform(async()=>{await api('sprints/'+board.value.selectedSprint.id,'DELETE');sprintFilter.value='backlog';await open(board.value.project.id);});}
async function quickCreate(title:string,done:()=>void){await perform(async()=>{await api('tasks','POST',{title,department_id:departmentId.value,project_id:board.value.project.id,workflow_id:board.value.selectedWorkflow?.id,workflow_column_id:columns.value[0]?.id,status:'pending',sprint_id:board.value.selectedSprint?.id||null});board.value=(await api(boardPath(board.value.project.id))).data;done();});}
async function sprintState(){await perform(async()=>{await api('sprints/'+board.value.selectedSprint.id,'PUT',{status:board.value.selectedSprint.status==='active'?'completed':'active'});board.value=(await api(boardPath(board.value.project.id))).data;});}
function showIssue(id:number,action=''){if(action==='assign'&&Array.isArray(board.value?.asignee)){const card=board.value.boardTasks.find((t:any)=>t.id===id);if(card){quickAssignment.value=card;return;}}issueAction.value=action;issue.value=id;}
function assignmentUpdated(task:any){const card=board.value?.boardTasks.find((t:any)=>t.id===task.id);if(card)Object.assign(card,task);}
function updated(e:Event){const data=(e as CustomEvent).detail;if(editor.value||task.value||busy.value)return;if(departmentOverview.value){void load();if(board.value&&Number(data.project_id)===board.value.project.id)void open(board.value.project.id);}else if(board.value&&Number(data.project_id)===board.value.project.id)void open(board.value.project.id);else if(!board.value)void load();}onUnmounted(()=>window.removeEventListener('pms:changed',updated));onMounted(async()=>{window.addEventListener('pms:changed',updated);const query=new URLSearchParams(window.location.search);const id=props.initialProject||(!query.get('section')||['project-board','project-departments'].includes(query.get('section')||'')?Number(query.get('project')):0);if(Number.isInteger(id)&&id>0){await open(id);const taskId=Number(new URLSearchParams(window.location.search).get('issue'));if(taskId>0)issue.value=taskId;}else{await load();if(props.createDepartment)newProject();}restoring.value=false;});
async function manageProject(){if(!page.value)await load();await editProject(board.value.project);}
function openUnallocated(){departmentId.value=null;departmentOverview.value=false;const url=new URL(location.href);url.searchParams.delete('department');history.replaceState(null,'',url);void open(board.value.project.id);}
function openDepartment(id:number){departmentId.value=id;departmentOverview.value=false;sprintFilter.value='backlog';const url=new URL(location.href);url.searchParams.set('department',String(id));history.replaceState(null,'',url);void open(board.value.project.id);}
function backToProjects(){const id=board.value?.project?.id;if(id)void selectProject(id);else{clearProjectSelection();void load();}}
function sortProjects(event:Event){const [key,direction]=(event.target as HTMLSelectElement).value.split(':');sortKey.value=key;sortAscending.value=direction==='asc';tablePage.value=1;}
function leads(p:any){return (p.users||[]).filter((u:any)=>u.roles?.some((r:any)=>['project_manager','team_leader'].includes(r.role_key)));}
async function viewProject(p:any){await perform(async()=>{preview.value=(await api('projects/'+p.id+'/departments')).data.project;});}
const activeClient=computed(()=>page.value?.clients?.find((client:any)=>Number(client.id)===clientId.value)||page.value?.projects?.find((project:any)=>Number(project.client_id)===clientId.value)?.client||null);

const overviewProjectId=ref<number|null>(null),overviewLoading=ref(false),departmentPanel=ref<HTMLElement|null>(null);
let overviewVersion=0;
async function selectProject(id:number){
 departmentOverview.value=true;departmentId.value=null;sprintFilter.value='';workflowFilter.value='';
 overviewProjectId.value=id;
 await open(id,true);
}
function rememberClient(project:any){
 if(!page.value&&project?.client_id&&clientId.value!==Number(project.client_id)){clientId.value=Number(project.client_id);const url=new URL(location.href);url.searchParams.set('client',String(clientId.value));history.replaceState(null,'',url);}
}
function clearProjectSelection(){
 overviewVersion++;overviewProjectId.value=null;overviewLoading.value=false;board.value=null;departmentOverview.value=false;departmentId.value=null;
 const url=new URL(location.href);for(const key of ['project','department','workflow','sprint','issue'])url.searchParams.delete(key);url.searchParams.set('section','projects');history.replaceState(null,'',url);window.dispatchEvent(new Event('pms:navigation'));
}
watch([search,statusFilter,approvalFilter],()=>{tablePage.value=1;});
</script>
<template><PmsFormDialog v-if="editor" :title="editor.id?'Edit project':'Create project'" subtitle="Set up the client, schedule, workflow, and project details." size="xl" centered @close="editor=null"><form class="admin-editor pms-form-modal" @submit.prevent="saveProject"><section class="project-form-section"><h6>Project information</h6><label><span>Name <span class="text-danger">*</span></span><input v-model="editor.name" required maxlength="255" placeholder="Enter project name"></label><label>Project Logo<small class="muted">JPG, JPEG, PNG, WebP or SVG - Maximum 2 MB.</small><input type="file" accept=".jpeg,.jpg,.png,.webp,.svg" @change="editor.image=($event.target as HTMLInputElement).files?.[0]"></label><label>Client<select v-model.number="editor.client_id" required><option disabled value="">Select client</option><option v-for="c in page?.clients" :key="c.id" :value="c.id">{{c.name}}</option></select><small class="muted">The project belongs to the client's company.</small></label><label>Departments<PmsMultiSelect v-model="editor.department_ids" :options="page?.departments||[]" label-key="dept_name" placeholder="Search and select departments"/><small class="muted">Search and select one or more participating departments.</small></label><label>Attachment<small class="muted">Documents, spreadsheets or images - Maximum 10 MB.</small><input type="file" accept=".pdf,.doc,.docx,.ppt,.pptx,.xls,.xlsx,.csv,.jpg,.jpeg,.png,.txt" @change="editor.attachment=($event.target as HTMLInputElement).files?.[0]"></label><label class="full-width">URL<input v-model="editor.url" type="url" placeholder="https://example.com"></label></section><section class="project-form-section"><h6>Project brief</h6><label class="full-width">Description<PmsDescriptionEditor v-model="editor.description"/></label></section><section class="project-form-section"><h6>Schedule and workflow</h6><label><span>Start Date <span class="text-danger">*</span></span><input v-model="editor.start_date" type="date" required></label><label>End date<input v-model="editor.end_date" type="date" :min="editor.start_date"></label><fieldset class="full-width"><legend>Workflows (required)</legend><label class="check" v-for="w in page?.availableWorkflows" :key="w.id"><input type="checkbox" :value="w.id" v-model="editor.workflow_ids">{{w.name}}</label></fieldset></section><div class="editor-actions"><button class="button primary" :disabled="busy||!editor.workflow_ids.length">{{editor.id?'Save project':'Create project'}}</button><button class="button" type="button" @click="editor=null">Cancel</button></div></form></PmsFormDialog>
<PmsFormDialog v-if="preview" :title="preview.name" size="lg" centered @close="preview=null"><div class="pms-project-preview-content"><img v-if="preview.image" :src="preview.image" :alt="preview.name"><table class="pms-table"><tbody><tr><th>Attachment</th><td><a v-if="preview.attachment" :href="preview.attachment" target="_blank" rel="noopener">Download attachment</a><span v-else>None</span></td></tr><tr><th>Link</th><td><a v-if="preview.url" :href="preview.url" target="_blank" rel="noopener">{{preview.url}}</a><span v-else>None</span></td></tr><tr><th>Status</th><td><span class="badge bg-label-primary">{{preview.status}}</span></td></tr><tr><th>Start Date</th><td>{{preview.start_date?.slice(0,10)||'-'}}</td></tr><tr><th>Due Date</th><td>{{preview.end_date?.slice(0,10)||'-'}}</td></tr></tbody></table><label class="form-label" for="project-preview-description">Description</label><textarea id="project-preview-description" class="form-control" readonly :value="preview.description||''" rows="6"></textarea></div><template #footer><button class="button" @click="preview=null">Close</button></template></PmsFormDialog><PmsFormDialog v-if="listDiscussion" title="Comments" size="xl" centered @close="listDiscussion=null"><PmsProjectChat :project-id="listDiscussion.id" :csrf="csrf"/></PmsFormDialog><PmsFormDialog v-if="listSubmission" :title="'Submissions: '+listSubmission.name" class="pms-project-submissions-dialog" @close="listSubmission=null"><PmsSubmissions type="project" :id="listSubmission.id" :csrf="csrf" :can-submit="listSubmission.users?.some((u:any)=>u.id===page?.userId)"/></PmsFormDialog><p v-if="error" class="notice admin-error" role="alert">{{error}}</p><template v-if="busy" role="status"></template>
<template v-if="restoring" role="status"></template><template v-else-if="!board||departmentOverview">
<PmsFormDialog v-if="assignment" title="Assign Project" size="assignment" centered @close="assignment=null"><form class="pms-assignment-form" @submit.prevent="assignProject"><label>Select Employee<PmsMultiSelect v-model="assignmentIds" :options="page.filteredUsers" label-key="name" placeholder="Choose employees" search-placeholder="Search employee or role..." empty-text="No employees found." :role-labels="true"/></label><div class="editor-actions"><button type="button" class="button" @click="assignment=null">Close</button><button class="button primary" :disabled="busy||!assignmentIds.length">{{busy?'Assigning...':'Assign'}}</button></div></form></PmsFormDialog>
<div class="pms-table-card pms-project-list"><div class="pms-table-heading pms-project-context-heading"><div class="pms-project-context"><small>CLIENT WORKSPACE / PROJECTS</small><h2>{{activeClient?.name||(clientId?'Client projects':'Projects')}}</h2><p>{{clientId?'Projects for this client. Choose a project to view its departments.':'Browse your accessible projects and their departments.'}}</p></div><button v-if="can('project-add')" class="button primary" @click="newProject"><i aria-hidden="true" class="ti ti-circle-plus"></i>Create</button></div><PmsTableControls :total="shown.length" v-model:page="tablePage" v-model:size="tableSize" v-model:search="search" search-placeholder="Search projects..."><select aria-label="Filter project status" v-model="statusFilter" @change="tablePage=1"><option value="">Status</option><option v-for="status in ['pending','progress','completed','delivered','cancelled']" :key="status" :value="status">{{status}}</option></select><select aria-label="Filter project approval" v-model="approvalFilter" @change="tablePage=1"><option value="">Approval</option><option value="pending">Pending</option><option value="approved">Approved</option><option value="rejected">Rejected</option></select><select aria-label="Sort projects" :value="sortKey+':'+(sortAscending?'asc':'desc')" @change="sortProjects"><option value="id:desc">Newest first</option><option value="id:asc">Oldest first</option><option value="name:asc">Name: A to Z</option><option value="name:desc">Name: Z to A</option><option value="tasks_count:desc">Most tasks</option></select></PmsTableControls><PmsProjectGrid :projects="paged" :selected-id="overviewProjectId" :permissions="permissions" :busy="busy" @select="selectProject" @preview="viewProject" @edit="editProject" @delete="deleteProject" @assign="assignment=$event;assignmentIds=[]" @tasks="viewTasks" @discussion="listDiscussion=$event" @submissions="listSubmission=$event" @status="projectStatus" @approval="approval" @remove-member="removeProjectUser"/><div v-if="!shown.length" class="pms-project-grid-empty"><i class="ti ti-folders" aria-hidden="true"></i><h3>{{page?.projects?.length?'No matching projects':'No projects yet'}}</h3><p>{{page?.projects?.length?'Try a different search or filter.':'Projects for this client will appear here.'}}</p></div><PmsTableControls footer :total="shown.length" v-model:page="tablePage" v-model:size="tableSize"/></div>
<section v-if="overviewProjectId" id="pms-project-department-panel" ref="departmentPanel" class="pms-project-department-panel" :aria-busy="overviewLoading" aria-label="Project departments"><header class="pms-project-department-heading"><div><small>SELECTED PROJECT</small><h3>{{board?.project?.name||page?.projects?.find((project:any)=>project.id===overviewProjectId)?.name||'Project departments'}}</h3><p>Choose a department to open its backlog and sprints.</p></div><button v-if="board&&can('project-edit')" class="button" :disabled="busy||overviewLoading" @click="manageProject"><i class="ti ti-edit" aria-hidden="true"></i>Edit project</button></header><p v-if="overviewLoading" class="muted" role="status">Loading departments...</p><div v-else-if="board" class="pms-department-tiles"><button v-for="department in board.project.departments" :key="department.id" @click="openDepartment(department.id)"><i class="ti ti-layout-kanban" aria-hidden="true"></i><strong>{{department.dept_name}}</strong><span>Open sprint board &rarr;</span></button><button v-if="board.hasUnallocatedWork" @click="openUnallocated"><i class="ti ti-inbox" aria-hidden="true"></i><strong>Existing work</strong><span>Open work awaiting department allocation</span></button><p v-if="!board.project.departments?.length" class="muted">{{can('project-edit')?'No departments linked. Edit this project to add participating departments.':'No departments are available for your account in this project.'}}</p></div><p v-else-if="error" class="text-danger">Unable to load this project. Select it again to retry.</p></section></template>
<template v-else><div class="pms-project-board-context"><button class="button" @click="backToProjects"><i class="ti ti-arrow-left" aria-hidden="true"></i>Back to projects</button><span>{{board.project.client?.name||activeClient?.name||'Client workspace'}} / {{board.project.name}}<template v-if="board.boardDepartment"> / {{board.boardDepartment.dept_name}}</template></span></div><PmsSprintBoard :data="board" :permissions="permissions" :busy="busy" :workflow-filter="workflowFilter" :sprint-filter="sprintFilter" @workflow="workflowFilter=$event;open(board.project.id)" @sprint="sprintFilter=$event;open(board.project.id)" @new-sprint="sprintEditor={name:'',goal:'',start_date:'',end_date:'',status:'planned'}" @sprint-state="sprintState" @workload="openWorkload" @create="newTask" @quick-create="quickCreate" @open="showIssue($event)" @edit="showIssue($event,'edit')" @assign="showIssue($event,'assign')" @delete="showIssue($event,'delete')" @handoff="showIssue($event,'handoff')" @transfer="showIssue($event,'transfer')" @place="showIssue($event,'place')" @drag="dragged=$event" @drop="(column,position)=>drop(column,position)"/><div v-if="workloadOpen" class="pms-form-backdrop pms-offcanvas-backdrop pms-workload-sidebar" @click.self="workloadOpen=false" @keydown.esc="workloadOpen=false"><section class="pms-offcanvas" tabindex="-1" role="dialog" aria-modal="true" aria-label="Assignee workload"><header><div><h5>Assignee workload</h5><small class="text-muted">Project vs {{board.selectedSprint?.name||'Backlog'}}</small></div><button aria-label="Close workload" @click="workloadOpen=false"><i class="ti ti-x" aria-hidden="true"></i></button></header><div class="pms-offcanvas-body"><article v-for="person in board.workloadUsers" :key="person.id" class="pms-workload-person"><div class="d-flex justify-content-between"><div class="d-flex align-items-center gap-2"><img class="jira-avatar" :src="person.profile_img||'/pms-assets/assets/img/user-picture.png'" alt=""><strong>{{person.name}}</strong></div><div><span class="badge bg-label-primary">{{person.sprint_tasks_count}} current</span><div class="small text-muted mt-1">{{person.project_tasks_count}} project total</div></div></div><p v-for="t in person.tasks" :key="t.id"><button class="pms-project-link" @click="workloadOpen=false;showIssue(t.id)">{{t.title}}</button><span class="badge ms-1" :class="t.status==='completed'?'bg-label-success':'bg-label-secondary'">{{t.status.replaceAll('_',' ')}}</span></p></article><p v-if="!board.workloadUsers?.length" class="jira-empty">No users assigned to this project.</p></div></section></div><PmsFormDialog v-if="sprintEditor" :title="sprintEditor.id?'Edit sprint':'Create sprint'" @close="sprintEditor=null"><form class="pms-reference-form" @submit.prevent="saveSprint"><label class="full-width">Sprint name<input v-model="sprintEditor.name" required maxlength="120" placeholder="Sprint 1"></label><label class="full-width">Sprint goal<textarea v-model="sprintEditor.goal" maxlength="1000" rows="3"></textarea></label><label>Start date<input type="date" v-model="sprintEditor.start_date"></label><label>End date<input type="date" v-model="sprintEditor.end_date" :min="sprintEditor.start_date"></label><label v-if="!sprintEditor.id" class="check full-width"><input type="checkbox" :checked="sprintEditor.status==='active'" @change="sprintEditor.status=($event.target as HTMLInputElement).checked?'active':'planned'">Start immediately<small>Multiple sprints can be active in this project at the same time.</small></label><label v-else class="full-width">Status<select v-model="sprintEditor.status"><option value="planned">Planned</option><option value="active">Active</option><option value="completed">Completed</option></select></label><div class="editor-actions"><button type="button" class="button" @click="sprintEditor=null">Cancel</button><button class="button primary" :disabled="busy">{{sprintEditor.id?'Save sprint':'Create sprint'}}</button></div></form></PmsFormDialog><PmsFormDialog v-if="task" title="Create issue" wide @close="task=null"><form class="pms-reference-form" @submit.prevent="saveTask"><label class="full-width">Summary<input v-model="task.title" required maxlength="255"></label><label class="full-width">Description<PmsDescriptionEditor v-model="task.description"/></label><label>Workflow column<select v-model.number="task.workflow_column_id"><option v-for="c in columns" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>Priority<select v-model.number="task.priority"><option v-for="(label,i) in ['Low','Normal','High','Urgent']" :key="i" :value="i">{{label}}</option></select></label><label>Assignees<select multiple size="4" v-model="task.assignee_ids"><option v-for="p in board.asignee" :key="p.id" :value="p.id">{{p.name}}</option></select><small>Select one or more employees. Hold Ctrl/Cmd to select multiple.</small></label><label>Sprint<select v-model="task.sprint_id"><option value="">Backlog</option><option v-for="s in board.sprints" :key="s.id" :value="s.id">{{s.name}}</option></select></label><label>Due date<input type="datetime-local" v-model="task.due_date"></label><label>Attachments<small>PDF, Office, CSV, TXT, JPG, PNG, WebP, GIF or ZIP &middot; Up to 10 files, 10 MB each.</small><input type="file" multiple accept=".pdf,.doc,.docx,.ppt,.pptx,.xls,.xlsx,.csv,.txt,.jpg,.jpeg,.png,.webp,.gif,.zip" @change="task.attachments=Array.from(($event.target as HTMLInputElement).files||[])"></label><div class="editor-actions"><button type="button" class="button" @click="task=null">Cancel</button><button class="button primary" :disabled="busy">Create issue</button></div></form></PmsFormDialog>
</template><PmsMyWorkAssignees v-if="quickAssignment" :task="quickAssignment" :users="board.asignee" :csrf="csrf" @close="quickAssignment=null" @updated="assignmentUpdated"/><PmsTaskDetail v-if="issue" :id="issue" :initial-task="board?.boardTasks?.find((t:any)=>t.id===issue)" :initial-edit-options="board" :initial-action="issueAction" :csrf="csrf" :permissions="permissions" @close="issue=null;issueAction=''" @updated="open(board.project.id)"/>
<PmsFormDialog v-if="taskList" title="Project Tasks" size="xl" centered @close="taskList=null"><PmsTableControls :total="filteredTaskList.length" v-model:page="taskListPage" v-model:size="taskListSize" v-model:search="taskSearch"/><div class="pms-table-scroll"><table class="pms-table"><thead><tr><th>ID</th><th>Task Title</th><th>Investment Time</th><th>Assignees</th><th>Status</th></tr></thead><tbody><tr v-for="t in taskListRows" :key="t.id"><td>{{t.id}}</td><td>{{t.title}}</td><td>{{t.invest_time||'00:00:00'}}</td><td><div class="pms-project-leads"><span v-for="u in t.users" :key="u.id" class="pms-project-lead" :title="u.name"><img v-if="u.profile_img" :src="u.profile_img" :alt="u.name"><span v-else>{{u.name.charAt(0)}}</span></span><span v-if="!t.users.length" class="badge bg-warning">No Assignees</span></div></td><td><span class="badge" :class="t.status==='completed'?'bg-success':t.status==='in_progress'?'bg-primary':t.status==='pending'?'bg-secondary':'bg-warning'">{{t.status.replaceAll('_',' ').toUpperCase()}}</span></td></tr><tr v-if="!filteredTaskList.length"><td colspan="5">No tasks found.</td></tr></tbody></table></div><PmsTableControls footer :total="filteredTaskList.length" v-model:page="taskListPage" v-model:size="taskListSize"/><template #footer><button class="button" @click="taskList=null">Close</button></template></PmsFormDialog></template>
